import { Component, createMemo, onMount } from "solid-js";

import { defineLegacyComponent } from "#core/ui-next/components/fxs-solid-component.js";
import { Tab } from "#core/ui-next/components/tab.jsx";
import { useAudio } from "#core/ui-next/services/audio-support.js";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { ViewExperience } from "#core/ui-next/services/view-experience.js";

import { ScreenFrame } from "#base/ui-next/components/screen-frame.jsx";
import { DedicationTab } from "#base/ui-next/screens/legacies/dedication-tab.jsx";
import { LegaciesUnlocksTab } from "#base/ui-next/screens/legacies/legacies-civ-unlocks-tab.jsx";
import { createLegaciesScreenModel, LegaciesScreenContext } from "#base/ui-next/screens/legacies/legacies-model.js";
import { LegaciesTriumphTab } from "#base/ui-next/screens/legacies/legacies-triumphs-tab.jsx";

interface LegaciesScreenProps {
	ref?: HTMLDivElement | ((el: HTMLDivElement) => void);
}

export const LegaciesScreenComponent: Component<LegaciesScreenProps> = (_props) => {
	const model = createLegaciesScreenModel();
	const audio = useAudio("LegaciesPopup");
	const isMobile = ViewExperience() == UIViewExperience.Mobile;

	onMount(() => {
		audio("popup-open");
	});

	const handleOnClosing = () => {
		audio("popup-close");
	};

	const ornatePanelData = createMemo(() => {
		return {
			name: "Legacies-Screen-Frame",
			id: "legacies-screen-frame",
			topIconSrc: "url('blp:sub_legacy_color')",
			topIconClass: "size-10 -mt-1",
			topIconBackgroundTint: model.playerColor,
			backgroundImageSrc: model.bgSrc,
		};
	});

	return (
		<LegaciesScreenContext.Provider value={model}>
			<ScreenFrame
				name="Legacies-Screen"
				title="LOC_LEGACIES_TITLE"
				panelContext="screen-legacies"
				audioContext="LegaciesScreen"
				ornatePanelData={ornatePanelData()}
				onClosing={handleOnClosing}
				isFullscreen={isMobile}
			>
				<Tab class="w-full flex flex-col flex-auto pointer-events-auto relative">
					<Tab.TabList
						class={`${isMobile ? "w-192" : "w-187"} self-center text-base font-base mb-2`}
						nextHotkey="nav-next"
						previousHotkey="nav-previous"
						showNavHelp={!model.isShowingDetails()}
					/>
					<Tab.Output />
					<Tab.Item
						name="Triumphs"
						title={() => "LOC_LEGACIES_TRIUMPHS_TITLE"}
						body={() => <LegaciesTriumphTab />}
					/>
					<Tab.Item
						name="Unlocks"
						title={() => "LOC_LEGACIES_UNLOCKS_TITLE"}
						body={() => <LegaciesUnlocksTab />}
					/>
					<Tab.Item
						name="Dedications"
						title={() => "LOC_DEDICATIONS_TITLE"}
						body={() => <DedicationTab />}
					/>
				</Tab>
			</ScreenFrame>
		</LegaciesScreenContext.Provider>
	);
};

export const LegaciesScreen = ComponentRegistry.register({
	name: "LegaciesScreen",
	createInstance: LegaciesScreenComponent,
});

defineLegacyComponent("screen-legacies", { classNames: ["fullscreen"] }, () => {
	Input.setActiveContext(InputContext.Shell);
	return <LegaciesScreen />;
});
